interface ChatMediator {
  send(message: string, from: User): void;
  addUser(user: User): void;
}

class ChatRoom implements ChatMediator {
  private users: User[] = [];

  addUser(user: User): void {
    this.users.push(user);
  }

  send(message: string, from: User): void {
    for (const user of this.users) {
      if (user !== from) {
        user.receive(message, from);
      }
    }
  }
}

class User {
  constructor(
    private mediator: ChatMediator,
    public name: string,
  ) {}

  send(message: string): void {
    this.mediator.send(message, this);
  }

  receive(message: string, from: User): void {
    console.log(`${this.name} received from ${from.name}: ${message}`);
  }
}

const bus = new Map();

function on(event, handler) {
  const handlers = bus.get(event) ?? new Set();

  handlers.add(handler);
  bus.set(event, handlers);

  return () => handlers.delete(handler);
}

function emit(event, payload) {
  bus.get(event)?.forEach((handler) => handler(payload));
}

// Checkout announces, Cart listens — neither imports the other
emit("checkout:completed", { orderId: 42 });
